    readonly hour?: "numeric" | "2-digit";
    readonly minute?: "numeric" | "2-digit";
    readonly second?: "numeric" | "2-digit";
    readonly weekday?: "short" | "long" | "narrow";
    readonly hourCycle?: "h11" | "h12" | "h23" | "h24";
}

export type ChartDiagnostic = Readonly<{
    code: string;
    reason: string;
    path: string;
    message: string;
}>;

